import java.io.*;
import java.util.*;

public class Main {
    static class Reader {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
        long nextLong() {
            return Long.parseLong(next());
        }
        String nextStr() {
            return next();
        }
    }

    public static void main(String[] args) {
        Reader r = new Reader();
        PrintWriter pw = new PrintWriter(System.out);
        int T = 1;
        for (int t = 0; t < T; t++) {
            Solver s = new Solver(pw, r);
            s.run(T, t);
        }
        pw.flush();
    }
}

class Solver {
    PrintWriter out;
    Reader in;

    public Solver(PrintWriter out, Reader in) {
        this.out = out;
        this.in = in;
    }

    public void run(int total, int index) {
        int n = in.nextInt();
        int mod = in.nextInt();

        long[][] dp = new long[n][n * n + 5];
        dp[0][0] = 1;
        for (int i=1; i<n; i++) {
            for (int j=0; j<dp[0].length; j++) {
                for (int c=0; c<=i; c++) {
                    if (j - c >= 0) {
                        dp[i][j] += dp[i-1][j-c];
                        dp[i][j] %= mod;
                        if (dp[i][j] == 0) dp[i][j] += mod;
                    }
                }
            }
        }

        long[][] sumArr = new long[dp.length][dp[0].length];
        for (int i=0; i<dp.length; i++) {
            long s = 0;
            for (int j=0; j<dp[0].length; j++) {
                s += dp[i][j];
                s %= mod;
                if (s == 0) s += mod;
                sumArr[i][j] = s;
            }
        }

        long[] fact = new long[251001];
        fact[0] = 1;
        for (int i=1; i<fact.length; i++) {
            fact[i] = (fact[i-1]*i)%mod;
        }

        long[][] nCr = new long[501][501];
        nCr[0][0] = 1;
        for (int i=1; i<=500; i++) {
            nCr[i][0] = 1;
            for (int j=1; j<=i; j++) {
                nCr[i][j] = (nCr[i-1][j] + nCr[i-1][j-1])%mod;
            }
        }

        long totalRes = 0;
        for (int i=0; i<=n-2; i++) {
            int cnt = n - i;
            int pre = n - cnt;
            long comb = (nCr[n][pre] * fact[pre]) % mod;
            long sumTotal = 0;
            long[] lastDP = dp[cnt-2];
            long ssum = 0;
            long totalSum = 0;
            for (int j=2; j<dp[0].length; j++) {
                totalSum += sumArr[cnt-2][j-2]*(cnt-1);
                totalSum %= mod;

                long tempVal = lastDP[j] * totalSum;
                totalRes += tempVal;
                totalRes %= mod;

                ssum += sumArr[cnt-2][j-2];
                if (j - cnt - 1 >= 0) ssum -= sumArr[cnt-2][j - cnt - 1];
                ssum = (ssum + mod) % mod;

                totalSum -= ssum;
                totalSum = (totalSum + mod) % mod;
            }
            totalRes += (sumArr[cnt-2][0] * comb) % mod;
            totalRes %= mod;
        }
        out.println(totalRes);
    }
}
